    """True if the schedule expr runs at the minute of the datetime when."""
    spec = _parse(expr)
    return (
        when.minute in spec.minute_set
        and when.hour in spec.hour_set
        and when.month in spec.months
        and when.day in spec.days(when.year, when.month)
    )


def next_run(expr, after):
    """The first run of expr strictly after the datetime after, or None."""
    spec = _parse(expr)
    try:
        start = after.replace(second=0, microsecond=0) + datetime.timedelta(minutes=1)
    except OverflowError:
        return None
    try:
        limit = after + _LIMIT
    except OverflowError:
        limit = datetime.datetime.max
    year, month = start.year, start.month
    while (year, month) <= (limit.year, limit.month):
        if month in spec.months:
            for day in spec.days(year, month):
                date = datetime.date(year, month, day)
                if date < start.date():
                    continue
                found = _first_time(spec, (start.hour, start.minute) if date == start.date() else (0, 0))
                if found is None:
                    continue
                run = datetime.datetime(year, month, day, *found)
                return run if run <= limit else None
        month += 1
        if month > 12:
            year, month = year + 1, 1
    return None


def _first_time(spec, earliest):
    """The first (hour, minute) of the schedule at or after earliest on one day."""
    hour0, minute0 = earliest
    for hour in spec.hours[bisect_left(spec.hours, hour0):]:
        if hour == hour0:
            i = bisect_left(spec.minutes, minute0)
            if i < len(spec.minutes):
                return hour, spec.minutes[i]
        else:
            return hour, spec.minutes[0]
    return None

